#include <vector>
#include <queue>
#include <unordered_set>

using namespace std;

class Solution {
public:
    int snakesAndLadders(vector<vector<int>>& board) {
        int n = board.size();
        auto get = [&](int s) {
            int r = (s - 1) / n, c = (s - 1) % n;
            if (r % 2) c = n - 1 - c;
            return board[n - 1 - r][c];
        };

        queue<pair<int, int>> q;
        q.push({1, 0});
        vector<bool> visited(n * n + 1, false);
        visited[1] = true;

        while (!q.empty()) {
            auto [s, d] = q.front(); q.pop();
            if (s == n * n) return d;
            for (int i = 1; i <= 6 && s + i <= n * n; ++i) {
                int nxt = get(s + i);
                if (nxt == -1) nxt = s + i;
                if (!visited[nxt]) {
                    visited[nxt] = true;
                    q.push({nxt, d + 1});
                }
            }
        }
        return -1;
    }
};
